using System.Buffers.Binary;
using System.Text.Json;
using Lou.Core;
using Lou.Devices;
using Lou.Rendering;
using SkiaSharp;
using Xunit;
namespace Lou.Tests;

public sealed class DisplayCompatibilityTests
{
    private static byte[] HidReply(int pm=128,int sub=1){var b=new byte[36];new byte[]{0xda,0xdb,0xdc,0xdd}.CopyTo(b,0);b[4]=(byte)sub;b[5]=(byte)pm;b[12]=1;return b;}
    [Fact] public void Trofeo_report_has_one_report_id_and_a_landscape_jpeg_profile(){var report=new byte[37];HidReply().CopyTo(report,1);var p=new HidLcdProtocol().Parse(HidTransport.InputPayload(report));Assert.Equal((1280,480,128,1,true,0),(p.Width,p.Height,p.Pm,p.Sub,p.Jpeg,p.Rotation));Assert.Equal(513,HidTransport.OutputReport(new HidLcdProtocol().Handshake).Length);Assert.Equal(0,HidTransport.OutputReport(new HidLcdProtocol().Handshake)[0]);}
    [Theory][InlineData(36,0,240,240,false,false,0)][InlineData(49,0,240,320,false,true,90)][InlineData(58,0,240,320,false,false,90)][InlineData(54,4,360,360,false,false,0)][InlineData(54,1,360,360,true,false,0)][InlineData(100,1,320,320,false,true,0)][InlineData(128,2,1280,480,true,false,90)][InlineData(63,3,1600,720,true,false,0)][InlineData(65,5,1920,462,true,false,180)][InlineData(69,3,1920,440,true,false,0)][InlineData(18,5,960,320,true,false,180)]
    public void Hid_profiles_separate_codec_geometry_and_orientation(int pm,int sub,int w,int h,bool jpeg,bool be,int rotation){var p=new HidLcdProtocol().Parse(HidReply(pm,sub));Assert.Equal((w,h,jpeg,be,rotation),(p.Width,p.Height,p.Jpeg,p.BigEndian,p.Rotation));}
    [Fact] public void Unknown_or_malformed_replies_never_guess_a_square_panel(){Assert.Throws<NotSupportedException>(()=>new HidLcdProtocol().Parse(HidReply(255)));foreach(int n in new[]{0,8,19})Assert.Throws<InvalidDataException>(()=>new HidLcdProtocol().Parse(HidReply()[..n]));var b=HidReply();b[12]=2;Assert.Throws<InvalidDataException>(()=>new HidLcdProtocol().Parse(b));b=HidReply();b[0]=0;Assert.Throws<InvalidDataException>(()=>new HidLcdProtocol().Parse(b));Assert.Throws<InvalidDataException>(()=>HidTransport.InputPayload([1,2,3]));Assert.Throws<InvalidDataException>(()=>HidTransport.OutputReport(new byte[511]));}
    [Theory][InlineData(1)][InlineData(492)][InlineData(493)][InlineData(512)][InlineData(449999)]
    public void Hid_frames_roundtrip_across_report_boundaries(int size){var payload=Enumerable.Range(0,size).Select(i=>(byte)(i%251)).ToArray();var packets=new HidLcdProtocol().Frame(payload,1280,480,true).ToArray();Assert.All(packets,p=>Assert.Equal(512,p.Length));var wire=packets.SelectMany(p=>p).ToArray();Assert.Equal(new byte[]{0xda,0xdb,0xdc,0xdd,2,0,0,0},wire[..8]);Assert.Equal(1280,BinaryPrimitives.ReadUInt16LittleEndian(wire.AsSpan(8)));Assert.Equal(480,BinaryPrimitives.ReadUInt16LittleEndian(wire.AsSpan(10)));Assert.Equal(size,BinaryPrimitives.ReadInt32LittleEndian(wire.AsSpan(16)));Assert.Equal(payload,wire[20..(20+size)]);Assert.All(wire[(20+size)..],b=>Assert.Equal(0,b));}
    [Fact] public void Raw_hid_frame_uses_fixed_header_and_exact_raster_length(){var p=new HidLcdProtocol();var first=p.Frame(new byte[320*320*2],320,320,false).First();Assert.Equal(1,first[6]);Assert.Equal(240,BinaryPrimitives.ReadUInt16LittleEndian(first.AsSpan(8)));Assert.Equal(320,BinaryPrimitives.ReadUInt16LittleEndian(first.AsSpan(10)));Assert.Throws<InvalidDataException>(()=>p.Frame(new byte[10],320,320,false).ToArray());Assert.Throws<InvalidDataException>(()=>p.Frame(new byte[450000],1280,480,true).ToArray());}
    [Theory][InlineData(false)][InlineData(true)]public void Rgb565_has_known_colors_and_byte_order(bool be){using var b=new SKBitmap(3,2);b.SetPixel(0,0,SKColors.Red);b.SetPixel(1,0,SKColors.Lime);b.SetPixel(2,0,SKColors.Blue);b.SetPixel(0,1,SKColors.White);b.SetPixel(1,1,SKColors.Black);b.SetPixel(2,1,SKColors.Cyan);var bytes=PixelEncoding.Rgb565(b,be);ushort[] expected=[0xf800,0x07e0,0x001f,0xffff,0,0x07ff];for(int i=0;i<expected.Length;i++)Assert.Equal(expected[i],be?BinaryPrimitives.ReadUInt16BigEndian(bytes.AsSpan(i*2)):BinaryPrimitives.ReadUInt16LittleEndian(bytes.AsSpan(i*2)));}
    [Theory][InlineData(0)][InlineData(90)][InlineData(180)][InlineData(270)]
    public void Encoded_raster_has_negotiated_dimensions_and_rotated_corners(int rotation){int w=320,h=240;using var frame=new SKBitmap(rotation is 90 or 270?h:w,rotation is 90 or 270?w:h);using(var c=new SKCanvas(frame)){c.Clear(SKColors.Black);using var p=new SKPaint{Color=SKColors.Red};c.DrawRect(0,0,30,30,p);}
        var raw=PixelEncoding.Frame(frame,w,h,rotation,false,true);Assert.Equal(w*h*2,raw.Length);var point=rotation switch{0=>(5,5),90=>(w-6,5),180=>(w-6,h-6),_=>(5,h-6)};Assert.Equal(0xf800,BinaryPrimitives.ReadUInt16BigEndian(raw.AsSpan((point.Item2*w+point.Item1)*2)));
        using var decoded=SKBitmap.Decode(PixelEncoding.Frame(frame,w,h,rotation,true,false));Assert.Equal((w,h),(decoded.Width,decoded.Height));Assert.True(decoded.GetPixel(point.Item1,point.Item2).Red>220);
    }
    [Fact]public void Encoder_rejects_wrong_raster_shape(){using var b=new SKBitmap(320,240);Assert.Throws<InvalidDataException>(()=>PixelEncoding.Frame(b,320,240,90,false,false));}
    [Theory][InlineData("0416","5408",DisplayFamily.Ly)][InlineData("0416","5409",DisplayFamily.Ly1)][InlineData("0416","5302",DisplayFamily.HidType2)][InlineData("87AD","70DB",DisplayFamily.ChiZhu)][InlineData("0418","5303",DisplayFamily.HidType3)][InlineData("0418","5304",DisplayFamily.HidType3)][InlineData("0416","5406",DisplayFamily.Ali)][InlineData("0402","3922",DisplayFamily.Scsi)][InlineData("87CD","70DB",DisplayFamily.Scsi)]
    public void Only_exact_physical_usb_roots_are_candidates(string vid,string pid,DisplayFamily expected){Assert.Equal(expected,DisplayFamilies.Identify($@"USB\VID_{vid}&PID_{pid}\example"));Assert.Equal(DisplayFamily.Unknown,DisplayFamilies.Identify($@"USB\VID_{vid}&PID_{pid}&MI_00\example"));Assert.Equal(DisplayFamily.Unknown,DisplayFamilies.Identify($@"HID\VID_{vid}&PID_{pid}\example"));}
    [Fact] public void Identical_models_cannot_steal_each_others_hid_interface(){DisplayInterface[] paths=[new("path-a",@"USB\VID_0416&PID_5302\a"),new("path-b",@"USB\VID_0416&PID_5302\b"),new("PATH-A",@"USB\VID_0416&PID_5302\a")];Assert.Equal(new[]{"path-b"},WindowsInterfaces.ForDevice(paths,@"usb\vid_0416&pid_5302\B"));Assert.Empty(WindowsInterfaces.ForDevice(paths,@"USB\VID_0416&PID_5302\missing"));Assert.Single(WindowsInterfaces.ForDevice(paths,@"USB\VID_0416&PID_5302\a"));}
    [Fact] public void Known_unimplemented_transports_remain_disabled(){Assert.False(DisplayFamilies.CanStream(DisplayFamily.Scsi,"USBSTOR"));Assert.False(DisplayFamilies.CanStream(DisplayFamily.HidType3,"HidUsb"));Assert.False(DisplayFamilies.CanStream(DisplayFamily.Ali,"USBSTOR"));Assert.True(DisplayFamilies.CanStream(DisplayFamily.Ali,"WinUSB"));}
    [Fact] public void Winusb_path_matching_uses_full_identity_not_serial_prefix(){string id=@"USB\VID_0416&PID_5408\example";Assert.True(DeviceDiscovery.InterfaceMatches("##?#USB#VID_0416&PID_5408#EXAMPLE#{abc}",id));Assert.False(DeviceDiscovery.InterfaceMatches("##?#USB#VID_0416&PID_5408#example-other#{abc}",id));Assert.False(DeviceDiscovery.InterfaceMatches("##?#USB#VID_0416&PID_5408&MI_00#example#{abc}",id));}
    [Fact] public void Reconnection_checks_encoding_and_legacy_profiles_keep_jpeg(){var old=JsonSerializer.Deserialize<ConfirmedDisplay>("""{"InstanceId":"test","Width":480,"Height":480,"Pm":4,"Sub":5,"Rotation":0}""")!;Assert.True(old.Jpeg);var p=new PanelProfile(480,480,4,5,true,0,"");Assert.True(DeviceValidation.Matches(old,"test",p));Assert.False(DeviceValidation.Matches(old,"test",p with{Jpeg=false}));Assert.False(DeviceValidation.Matches(old,"test",p with{BigEndian=true}));}
    [Fact] public void Ly1_uses_its_own_pm_formula_and_unpadded_command(){var reply=new byte[512];reply[0]=3;reply[1]=255;reply[8]=1;reply[20]=1;reply[22]=2;var p=new LyProtocol(true).Parse(reply);Assert.Equal((50,2,240,320,false,true),(p.Pm,p.Sub,p.Width,p.Height,p.Jpeg,p.BigEndian));var packet=new LyProtocol(true).Frame(new byte[492],1280,480,true).Single();Assert.Equal(512,packet.Length);Assert.Equal(2,packet[8]);Assert.Equal(1,BinaryPrimitives.ReadUInt16LittleEndian(packet.AsSpan(9)));Assert.Throws<InvalidDataException>(()=>new LyProtocol(true).Frame([1],240,320,false).ToArray());}
    [Theory][InlineData(0x36,240,320,false)][InlineData(0x65,320,320,true)][InlineData(0x66,320,320,true)]
    public void Ali_f5_handshake_and_frame_are_bounded(int identity,int w,int h,bool be){var protocol=new AliProtocol();Assert.Equal(1040,protocol.Handshake.Length);var reply=new byte[14];reply[0]=(byte)identity;var p=protocol.Parse(reply);Assert.Equal((w,h,false,be),(p.Width,p.Height,p.Jpeg,p.BigEndian));var wire=protocol.Frame(new byte[w*h*2],w,h,false).SelectMany(p=>p).ToArray();Assert.Equal(new byte[]{0xf5,1,1,0,0xbc,0xff,0xb6,0xc8},wire[..8]);Assert.Equal(w*h*2,BinaryPrimitives.ReadInt32LittleEndian(wire.AsSpan(12)));Assert.Equal(16,protocol.AckLength);Assert.Throws<InvalidDataException>(()=>protocol.Frame([1],w,h,false).ToArray());}
    [Fact] public void Hid_session_does_not_read_an_ack_or_count_a_failed_frame(){var fake=new HidFake();using var session=new LcdSession(fake,new HidLcdProtocol(),2,131);session.Send([0xff,0xd8,0xff,0xd9]);Assert.Equal(1,fake.Reads);Assert.Equal(1,session.Frames);fake.Disconnected=true;Assert.Throws<IOException>(()=>session.Send([1]));Assert.Equal(1,session.Frames);}
    private sealed class HidFake:IBulkTransport{public int Reads;public bool Disconnected;public byte[] Read(byte endpoint,int length){Reads++;return HidReply();}public void Write(byte endpoint,byte[] bytes){if(Disconnected)throw new IOException("Disconnected");Assert.Equal(512,bytes.Length);}public void Dispose(){}}
    [Theory][InlineData(1280,480)][InlineData(1600,720)][InlineData(960,320)][InlineData(854,480)][InlineData(360,360)][InlineData(240,320)][InlineData(640,172)]
    public void New_formats_render_all_pages_in_both_languages(int width,int height){using var renderer=new UniversalRenderer("missing-assets");foreach(var language in Enum.GetValues<AppLanguage>())foreach(var page in Enum.GetValues<PageId>())foreach(var data in new[]{Snapshot.Empty,Snapshot.Simulation()}){using var bitmap=renderer.Render(page,data,new(){Width=width,Height=height,Night=false,Language=language},new(2026,10,17,12,30,0),0);Assert.Equal((width,height),(bitmap.Width,bitmap.Height));Assert.Equal(255,bitmap.GetPixel(0,0).Alpha);}}
}
